//! The errno `WindowsError` reports for a Windows error code. Generated by
//! `generate_winerror_map.py` from the reference interpreter's results.

pub fn winerror_to_errno(code: i32) -> i32 {
    match code {
        2..=3 | 15 | 18 | 53 | 67 | 161 | 206 => 2,
        4 => 24,
        5 | 16 | 19..=36 | 65 | 82..=83 | 108 | 132 | 158 | 167 => 13,
        6 | 114 | 130 => 9,
        7..=9 | 1816 => 12,
        10 => 7,
        11 | 188..=202 => 8,
        17 => 18,
        80 | 183 => 17,
        89 | 164 | 215 => 11,
        109 => 32,
        112 => 28,
        128..=129 => 10,
        145 => 41,
        _ => 22,
    }
}
